(()=>{const t=document.getElementById('theme'),b=document.getElementById('backtop'),links=[...document.querySelectorAll('.toclinks a')];t?.addEventListener('click',()=>{document.body.classList.toggle('dark');t.setAttribute('aria-pressed',String(document.body.classList.contains('dark')))});window.addEventListener('scroll',()=>{b?.classList.toggle('show',scrollY>550);let active='';for(const s of document.querySelectorAll('.article-section'))if(s.getBoundingClientRect().top<160)active='#'+s.id;links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')===active))},{passive:true});b?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));})();